insert into matcha_articles (url, lang, prefecture_code, title, body, images, published_at, place, text_attribution, text_attribution_url)
values
(E'https://matcha-jp.com/cn/25430', E'zh-Hans', 17, E'【紧邻金泽站】一站尽享购物、美食与特产——金泽Forus完全攻略！', E'如果计划游览北陆・石川，一定不要错过从金泽站东口步出就能到达的购物胜地——“金泽Forus”。这里不仅汇聚了各大热门时尚品牌和精美化妆品，还有丰富的特色土产可以挑选，更有当地美食让你大快朵颐。本文将带你一探金泽Forus的魅力，体验购物与美食的完美结合。\n\n金泽Forus是一座紧邻金泽站的便利购物中心。这一次，我们将毫无保留地为大家介绍金泽Forus的魅力。\n\n其中冬季的“雪吊”尤为有名，这是防止积雪压断树枝的传统技法，美感十足，极具观赏价值。\n\n“金泽城”是江户时代(1603年～1868年)加贺藩前田家的居城。这里以洁白的五十间长屋（俗称多闻橹，曾是武器仓库）和精美的石墙而著称。', E'["https://resources.matcha-jp.com/resize/720x2000/2026/05/07-263725.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/21-239235.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/23-239325.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/23-239326.webp"]'::jsonb, E'2025-09-01'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/20754', E'zh-Hans', 17, E'金泽的热门景点 - 兼六园有什么特色？介绍其历史、营业时间和停车场', E'这是一篇关于金泽代表性旅游景点 - 兼六园的特色摘要文章。除了介绍兼六园的概况和历史外，还包括了樱花和红叶等季节的亮点、营业时间、入场费用、自驾汽车和电车・巴士的交通方式、停车场，以及周边推荐的停车场和和服租借店等内容。\n\n金泽兼六园作为日本三名园之一，若要造访这座美丽的庭园，事先了解其特色和历史将使您在实际造访时更深入地了解和欣赏其魅力。\n\n本文将详细介绍兼六园每个季节的特色、入场方式以及如何更享受穿着和服租借等观光活动。\n\n兼六园是位于日本石川县金泽市的代表园之一。与茨城县水户市的偕乐园、岡山县岡山市的后乐园并列为「日本三名园」、「日本三大庭园」而广为人知。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189955.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189956.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189957.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189958.webp"]'::jsonb, E'2024-08-07'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/3973', E'zh-Hans', 18, E'赏花推荐！石川、富山、福井之北陆3县的绝景樱花5选', E'因为北陆新干线的开通，北陆地方变得容易前往。本篇介绍春天前往必看的推荐樱花！\n\n北陆地方是指石川县、富山县、福井县等3县。位于日本本州北侧，面朝日本海。以前从东京前往此地的交通方式十分有限，自北陆新干线开通以来，从东京前往此地变得容易，故而众多游客纷纷来访北陆。\n\n2018年北陆地区的开花日和盛开日如下。2019年的预计情况根据公开信息，相继更新。\n\n北陆3县中知名度最高的是石川县。这里有北陆小京都之称，有具有历史怀旧感的赏樱名胜。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/02/06-17639.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/06-17634.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/06-17635.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/06-17633.webp"]'::jsonb, E'2017-02-21'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/9571', E'zh-Hans', 18, E'从金泽可当日往返！福井县必游观光景点＆美食13选', E'位于北陆地方的福井县，拥有众多看点，如绝景东寻坊(Toujinbou)和冬季美味越前(Echizen)蟹等！ 因为从热门城市金泽可当日往返，推荐组合旅行。本文为初次造访福井县的人们介绍必游观光景点和美食等模范旅游路线。\n\n位于日本北陆地方的福井县，面朝大海，由南向北狭长地延伸，北部和南部的方言和文化各异。北部与金泽所在的石川县接壤，是一处拥有深厚北陆地方特有文化根源的地方。此外，南部临近京都，自古以来便深受关西地区文化的影响。\n\n还有，这里四季分明，除了应季美景之外，夏天可品尝海胆和牡蛎(Kaki)、冬天可品尝螃蟹和河豚等美味，物产丰富。\n\n福井县至今出土了大量恐龙化石，站前广场也以此为宣传点，设置了一个实物大小的可动恐龙纪念碑和脚印(复制)，并设有以恐龙为主题的错觉艺术作品。', E'["https://resources.matcha-jp.com/resize/720x2000/2020/04/03-100842.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/03-100846.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/03-100847.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/25-100242.webp"]'::jsonb, E'2020-05-28'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/5920', E'zh-Hans', 18, E'【北陆】春烂漫！福井县在地人推荐赏樱景点8选', E'MATCHA福井当地小编，为大家整理了北陆福井县的赏樱景点8选，足羽山公园,丸冈城,西山公园等地，快来看看福井有什么浪漫樱花景致吧。\n\n春游日本，赏樱当然是不可错过的重头戏！MATCHA福井在地小编，整理了福井县的赏樱景点8选。北陆地区的福井因纬度较高，樱花绽放比起关东、四国等地区较晚一、两个礼拜，动身前往赏樱前，先跟着小编来看看福井有什么浪漫樱花景致吧！ 2019年预测福井开花日期为3月29日\n\n说到福井的樱花景点，在地人绝对首先推荐入选“樱花百选”的“足羽川河畔樱花并木”。足羽川是流经福井市的一条大河，靠近市中心段的河堤上有约600棵的染井吉野樱并排而种，绵延2.2公里之长。福井市的樱花祭就在这一带的河畔边举行，所以人潮相对会比较多一些，热闹但不至于拥挤，还是能优闲地赏樱。\n\n樱花并木分列河堤两旁，漫步期间，宛如穿过粉红色隧道。有时候，春风一吹，花瓣飘落翩翩飞舞，浪漫至极。2019的福井樱花祭从3月30日到4月14日。届时足羽河畔的餐厅、店家都会推出期间限定的赏樱特别菜色或优惠。京福巴士于期间的周六、周日及假日特别行驶市内赏樱周游巴士，乘车费一律200日元，非常划算。详细情报请参考官网。 查看资讯 第34届福井市樱花祭 第34届福井市樱花祭 View Map \' 地址 足羽河原堤防・足羽山・福井城址など Wi-Fi 无 信用卡及其使用种类 无 最近车站 JR福井站 交通方式 JR福井站步行15分钟 费用 免费 电话号码 福井市おもてなし観光推進課 0776-20-5346 官网 第34届福井市樱花祭', E'["https://resources.matcha-jp.com/resize/720x2000/2018/03/27-51151.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/27-51152.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/27-51153.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/27-51154.webp"]'::jsonb, E'2018-04-05'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/6352', E'zh-Hans', 19, E'富士山', E'63公尺，是日本国内的最高峰。富士山顶冬季积雪，直至次年6、7月才会融化，在管理上属于本州地区的富士箱根伊豆国立公园范围内。\n\n在富士山山麓周围，分布着5个淡水湖，统称富士五湖，是日本著名的观光度假名胜地。富士山有4个主要的登山口，分别为富士宫口、须走口、御殿场口、富士吉田（河口湖）口等，其中前三个登山入口都在静冈县内。\n\n富士山被日本人视为圣山，不但名列日本百名山，同时也是日本三名山之一，在古代文献中亦被称为不二、不尽或是富慈，也经常被称作芙蓉峰、富嶽或富岳。\n\n自古以来，这座山的名字就经常在日本的传统诗歌和歌中出现。富士山与樱花、新干线并列为日本的国家象征。富士山与浅间神社等范围以富士山于2013年6月22日以精神信仰与艺术层面正式获选列入世界文化遗产，是日本的第17个世界遗产（第13个世界文化遗产）。富士山除了特指此座山脉，还有一系列“乡土富士”，即遍布日本全国各地带有“富士”名称的山，比如羊蹄山等外型相似的山脉。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/07/24-59004.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/24-58984.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/24-58985.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/24-58992.webp"]'::jsonb, E'2019-04-05'::timestamptz, E'富士山', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%AF%8C%E5%A3%AB%E5%B1%B1'),
(E'https://matcha-jp.com/cn/4995', E'zh-Hans', 19, E'『小编的第一次』一辈子一定要爬一次！富士山登顶攻略', E'日本的第一高峰富士山，每年限定7、8月开放登山，不仅日本人热爱攀登，外国旅客也趋之若鹜。究竟登富士山有什么魅力？MATCHA带你从行程准备到五合目四条登山路线说谜名到攻顶下山一起走一遭！\n\n大家对富士山的印象，势必是有着白头（冠雪）的典型模样吧？然而，富士山的登山季节，则是必须等山顶积雪退去的夏季才能攀爬，每年的开山季节约落在7、8月，以去年（登山在2017年）和今年（2018年）来说是落在7月1日～9月10日，周末人潮众多，尤其8月中“山之日”假期，可说是整座山头都是登山客“排队”爬山。\n\n吉田线是所有路线中，最多登山客选择的路线，登山口（富士Subaruline付费道路五合目）有不少商店，回程可购买伴手礼或是上山前下山后稍事休息、用餐。\n\n距离山顶标高约1,400公尺，往复约14公里，上山约需要6个小时，下山则约3个小时30分钟。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/09/04-35294.webp","https://resources.matcha-jp.com/resize/720x2000/2017/09/04-35296.webp","https://resources.matcha-jp.com/resize/720x2000/2017/09/04-35297.webp"]'::jsonb, E'2018-09-03'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/25753', E'zh-Hans', 19, E'[长野/山梨]秋季旅行 - 秋季赏枫完全指南 | 不容错过的推荐景点', E'秋季的长野和山梨，空气清新，气候宜人，是欣赏富士山、湖泊、古刹、城市景观和秋叶的绝佳去处。这里空气清新，气候宜人，是散步、摄影、阅读和品尝美食的绝佳去处，绝对是秋季周末度假的完美选择。\n\n说到日本的秋天，色彩缤纷的秋叶无疑是一大亮点。长野县和山梨县从东京都交通便利，各景点之间的往返也相对便捷，是想要欣赏秋叶的游客的理想目的地。\n\n长野县和山梨县遍布着众多美丽的红叶景点，融合了富士山、湖泊、古刹和历史悠久的街道景观。本文将详细介绍红叶的魅力和推荐景点，重点介绍新仓山浅间公园、富士河口湖、善光寺、云场池、旧轻井泽等人气景点。\n\n新仓山浅间公园也是著名的赏樱胜地，春天可以欣赏盛开的樱花，背景是五重塔和富士山。秋天，红黄相间的枫树和银杏树环绕着五重塔，与白雪皑皑的富士山形成鲜明对比，蔚为壮观。这里不仅有众多国内外游客，一年四季都可以欣赏到美丽的景色。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/09/05-243455.webp","https://resources.matcha-jp.com/resize/720x2000/2025/09/05-243456.webp","https://resources.matcha-jp.com/resize/720x2000/2025/09/05-243457.webp","https://resources.matcha-jp.com/resize/720x2000/2025/09/05-243458.webp"]'::jsonb, E'2025-09-05'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/25766', E'zh-Hans', 20, E'【信州、长野】来一场秋日之旅吧！长野惠比寿花火大会与信州的魅力', E'每年11月在长野市举办的长野惠比寿花火大会，以秋冬特有的在晴空下绽放的烟火而闻名。烟火拥有与夏季不同的鲜艳之美，搭配秋叶和温泉，让您享受一场别具一格的信州秋季之旅。\n\n说到日本的烟火大会，很多人会想到盛夏的夜空。穿着浴衣漫步在小吃摊，享受一夜的乐趣，忘却酷暑，是典型的夏季活动。然而，每年11月下旬在长野县长野市举办的长野惠比寿烟火大会却打破了常规。这个在秋冬季节举办的日本罕见烟火大会，在清凉的空气中绽放的绚丽灯光，带来与夏季截然不同的感受。\n\n该烟火大会始于1899年（明治32年）。据说起源于以善光寺为代表的寺院小镇长野县，当时当地民众与惠比寿光市场联合举办烟火大会。自那时起，已有120多年历史，深受人们喜爱。\n\n这项活动的独特之处在于，只有经验丰富的烟火师才能参加。这是一个烟火制作者相互竞争的舞台，能够获得认可是莫大的荣誉。正因如此，它被称为“成功的烟火”，也成为年轻烟火制作者展翅高飞、成为技艺精湛的烟火艺术家的舞台。即使在今天，它仍被认为是全国质量最高的比赛之一。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/09/08-243609.webp","https://resources.matcha-jp.com/resize/720x2000/2025/09/08-243614.webp","https://resources.matcha-jp.com/resize/720x2000/2025/09/08-243610.webp","https://resources.matcha-jp.com/resize/720x2000/2025/09/08-243611.webp"]'::jsonb, E'2025-09-08'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/25615', E'zh-Hans', 20, E'[长野]北志贺三大滑雪胜地指南：滑雪、温泉、观赏雪猴！', E'从东京到北志贺的三大滑雪胜地！享受适合初学者和高级滑雪者的雪道，享受蓬松的粉雪，滑雪后，还可以泡温泉、品尝当地美食，放松身心。体验吉卜力风格的建筑，在金具屋旅馆体验“九旬斋”浴池之旅，观赏雪猴，享受冬季自然漫步。这是您完整的冬季旅行指南。\n\n冬季来临，北志贺地区吸引了来自日本各地的滑雪爱好者和单板滑雪爱好者。该地区交通便利，拥有三大滑雪场，从初学者到高级滑雪者都能尽享乐趣：北志贺小丸山滑雪场、X-JAM高井富士滑雪场及夜濑温泉滑雪场，以及龙王滑雪公园。从亲子滑雪的初体验，到高级滑雪者的自由式滑雪，这里提供丰富多彩的滑雪方式。本文将全面介绍北志贺三大滑雪场，涵盖交通、住宿、滑雪体验、雪质差异，甚至还有在雪场畅玩一天后可以享用的美食和温泉。\n\n火车：从东京站乘坐新干线到长野站约1小时30分钟。从长野站出发，您可以乘坐JR或私铁前往最近的车站。享受舒适的火车旅程，同时欣赏不断变化的风景。\n\n如果您乘坐高速巴士，东京站和新宿站都有直达的接驳巴士，有些甚至直达各个滑雪场。这对于行李较多或驾驶技术不熟练的游客来说非常方便，而且抵达后还可以立即开始滑雪。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/08/19-241618.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/19-241617.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/19-241621.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/19-241620.webp"]'::jsonb, E'2025-08-19'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/25015', E'zh-Hans', 20, E'諏訪湖', E'诹访湖（日语：諏訪湖／すわこ，罗马化：Suwa-ko）是位于日本长野县境内冈谷市、诹访市、诹访郡下诹访町交界处的湖泊，为日本河川法上一级河川天龙川的发源地。\n\n该湖是湖沼水质保全特别措置法指定湖沼。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/05/27-234684.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/28-234764.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/28-234762.webp","https://place.matcha-jp.com/resize/720x2000/2025/05/28-15-16-52-31397de8d8ba71770adcea1f7a93d4023cb3.webp"]'::jsonb, E'2025-05-28'::timestamptz, E'諏訪湖', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E8%AB%8F%E8%A8%AA%E6%B9%96'),
(E'https://matcha-jp.com/cn/22204', E'zh-Hans', 21, E'【2024-25】岐阜县的推荐滑雪场11选，周边露营场、儿童乐园介绍！', E'岐阜县拥有丰富多样的滑雪场，包括夏季仍可滑雪的设施以及配备温泉的设施。本篇文章将介绍适合高阶滑雪者、初学者及家庭游客都能安心享受的滑雪场。希望能成为您选择出游地点的参考！\n\n岐阜县的吸引力在于其交通便利以及多样的滑雪场。岐阜县的滑雪场通常在每年12月到4月期间开放。由于有些滑雪场提供季卡，因此建议在使用前先进行确认。\n\n▼岐阜县的滑雪场从名古屋的交通便利！ ▼岐阜县的著名滑雪场4选｜有露营场和全天候营业的滑雪场\n\n如果您想尽情享受多样化的滑雪体验，以下四个滑雪场是非常推荐的选择。其中一些还配有露营场的大型滑雪场。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/10/22-204287.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/22-204289.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/22-204292.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/22-204294.webp"]'::jsonb, E'2024-10-23'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/4109', E'zh-Hans', 21, E'【岐阜县】当天往返，飞弹高山下吕温泉一日游～推荐温泉，旅馆等～', E'下吕温泉位于岐阜县下吕市，是日本三大名泉之一。从飞弹高山出发一个小时左右就可以抵达。有很多季节性的活动，例如2月份的田神祭，8月份的下吕温泉祭等。本文小编为大家介绍下吕温泉的访问方法，温泉的功效，以及可以当天往返的温泉以及旅馆等讯息。\n\n下吕温泉位于东海地方、岐阜县下吕市。江戸时代的儒学家 (*1)林 罗山把有马温泉，草津温泉，下吕温泉并称为日本的三大名泉，下吕温泉至今仍是日本三大名泉之一。\n\n温泉街位于飞弹川旁。有一些沿川而建的旅馆呀温泉的露天浴池可以看到川水的流动，以及葱葱绿树。下吕温泉有很多季节性的活动，例如2月份的田神祭，8月份的下吕温泉祭等，所以您可以趁着有祭祀活动的时候来。\n\n从岐阜县最有名的观光地飞弹高山的高山站乘坐电车到下吕温泉只需要1个小时左右。观光过高山之后到下吕温泉缓解一下旅途中的疲劳是一个非常不错的选择。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/03/03-20388.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/03-20386.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/03-20394.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/03-20389.webp"]'::jsonb, E'2018-02-17'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/4436', E'zh-Hans', 21, E'夏季限定！看得到“鸬鹚捕鱼”的最佳景点5选、参观期间、费用', E'「鸬鹚捕鱼」是渔民藉由鸬鹚钻入水中捕捉鱼类的一种日本传统的捕鱼技法。日本三大鸬鹚捕鱼分别在岐阜县的长良川、爱媛县大洲市的肱川、大分县的三隅川。今天我们要来介绍鸬鹚捕鱼是什么样的捕鱼技法，还有哪里可以看到这样的技法(季节、费用等等)。\n\n鸬鹚捕鱼是一种利用在日本栖息的鸬鹚属鸬鹚科鸟「鸬鹚(Lú cí)」来捕鱼的一种传统渔业，在每年的5月〜9月可以看得到。鸬鹚有着把抓到的鱼暂时放在喉咙再把猎物吐出来的习性，去利用这样的习性去鸬鹚捕鱼。先让鸬鹚抓到香鱼，然后人类用一些方法让鸬鹚把鱼给吐出来。\n\n鸬鹚捕鱼会由1〜3位渔夫搭配5～12只的鸬鹚来进行。晚上的时候会先乘舟出航，用舟前端的篝火(かがりび)把水面照亮去吓香鱼，当香鱼的动作变得迟缓的时候派出鸬鹚去捕捉。在鸬鹚的脖子上有绑着宽松的绳子，小只的鱼就直接掉进胃里，比较大只的鱼就会留在喉咙。\n\n鸬鹚捕鱼有着长远的历史，距今约1400~1300年前在岐阜县的长良川等日本的各地就已经看得到这个技法的踪迹。现在日本三大鸬鹚捕鱼分别在岐阜县的长良川、爱媛县大洲市的肱川(ひじかわ)、大分县的三隅川(みくまがわ)。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/05/18-26698.webp","https://resources.matcha-jp.com/resize/720x2000/2017/05/18-26696.webp","https://resources.matcha-jp.com/resize/720x2000/2017/05/23-26996.webp","https://resources.matcha-jp.com/resize/720x2000/2017/05/18-26699.webp"]'::jsonb, E'2017-10-25'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/6031', E'zh-Hans', 22, E'富士山', E'63公尺，是日本国内的最高峰。富士山顶冬季积雪，直至次年6、7月才会融化，在管理上属于本州地区的富士箱根伊豆国立公园范围内。\n\n在富士山山麓周围，分布着5个淡水湖，统称富士五湖，是日本著名的观光度假名胜地。富士山有4个主要的登山口，分别为富士宫口、须走口、御殿场口、富士吉田（河口湖）口等，其中前三个登山入口都在静冈县内。\n\n富士山被日本人视为圣山，不但名列日本百名山，同时也是日本三名山之一，在古代文献中亦被称为不二、不尽或是富慈，也经常被称作芙蓉峰、富嶽或富岳。\n\n自古以来，这座山的名字就经常在日本的传统诗歌和歌中出现。富士山与樱花、新干线并列为日本的国家象征。富士山与浅间神社等范围以富士山于2013年6月22日以精神信仰与艺术层面正式获选列入世界文化遗产，是日本的第17个世界遗产（第13个世界文化遗产）。富士山除了特指此座山脉，还有一系列“乡土富士”，即遍布日本全国各地带有“富士”名称的山，比如羊蹄山等外型相似的山脉。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/05/22-54543.webp","https://resources.matcha-jp.com/resize/720x2000/2018/04/24-52908.webp","https://resources.matcha-jp.com/resize/720x2000/2018/05/22-54539.webp","https://resources.matcha-jp.com/resize/720x2000/2018/04/24-52909.webp"]'::jsonb, E'2018-11-12'::timestamptz, E'富士山', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%AF%8C%E5%A3%AB%E5%B1%B1'),
(E'https://matcha-jp.com/cn/25447', E'zh-Hans', 22, E'从东京出发仅需两小时，探索伊豆修善寺全新魅力之旅 —— 地藏雕刻与芥末特别体验', E'自古以来便以温泉胜地闻名的伊豆修善寺地区，被誉为「小京都」的这座小镇，是一处能够享受只有在此地才能体验的独特旅游乐趣的观光胜地。 本文将为您介绍在修善寺地区可以亲身体验的美食、文化与传统等特别体验。\n\n自古以來就以溫泉鄉聞名的修善寺，實際上也是被認定為「世界農業遺產」的山葵栽培聖地。在這裡，您可以品嚐到運用清澈水源孕育出的山葵，以及當地的精釀啤酒、日本清酒與葡萄酒等，充分展現大自然恩賜的在地美味。\n\n在那样的城镇中心，有一座被传说由约1200年前对日本佛教影响深远的高僧——弘法大师空海所开创的「修禅寺」。这个地方拥有将军源赖家被幽禁的历史背景，至今仍能感受到某种庄严的气氛。\n\n这次将为您介绍几个能深入体验修善寺文化、美食与历史的景点。邀您展开一场五感皆能感受的全新修善寺之旅。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/07/23-239318.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/23-239451.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/23-239319.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/23-239494.webp"]'::jsonb, E'2025-09-26'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/10541', E'zh-Hans', 22, E'濱名湖橋', E'滨名湖桥（日语：浜名湖橋／はまなこばし）是一座横跨滨名湖的四车道公路桥，位于日本静冈县滨松市。这座桥横跨滨名湖北部，邻近馆山寺，东名高速公路从桥上经过，为全长603公尺的曲线钢结构箱梁桥，其四个连续跨度总长140公尺，支撑点的箱梁截面均为6×6公尺。\n\n并以平缓的倒S形曲线横跨滨名湖，连接了滨松市中央区的滨松西交流道和同市滨名区的滨名湖服务区。', E'["https://resources.matcha-jp.com/resize/720x2000/2021/05/27-114409.webp","https://resources.matcha-jp.com/resize/720x2000/2021/05/27-114410.webp","https://resources.matcha-jp.com/resize/720x2000/2021/05/27-114411.webp","https://resources.matcha-jp.com/resize/720x2000/2021/05/27-114412.webp"]'::jsonb, E'2021-06-08'::timestamptz, E'濱名湖橋', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E6%BF%B1%E5%90%8D%E6%B9%96%E6%A9%8B'),
(E'https://matcha-jp.com/cn/4733', E'zh-Hans', 23, E'直击名古屋乐高乐园！必玩必吃全攻略！', E'位于名古屋的LEGOLAND® Japan乐高乐园，总面积虽然只有9.3公顷，不过麻雀虽“小”五脏具全，园内七大区各有特别，如果时间不够也挺难做决定，让小编帮大家整理5大重点攻略，去到就不用烦啦！\n\n位于名古屋的LEGOLAND® Japan，总面积虽然只有9.3公顷，不过麻雀虽“小”五脏具全，园内七大区各有特别，如果时间不够也挺难做决定，让小编帮大家整理5大重点攻略，去到就不用烦啦！\n\n作为主场代表的名古屋城高2.1米，震撼全场！同场还有另一代表OASIS 21，看完后有兴趣可以直接加入行程当中。\n\n平常去东京总是人很多，但看缩景就不用跟人挤啦！涩谷十字路口、东京站、台场高达、浅草寺让你任拍，可爱之处在于109变了601！', E'["https://resources.matcha-jp.com/resize/720x2000/2017/07/30-32450.webp","https://resources.matcha-jp.com/resize/720x2000/2017/07/30-32449.webp","https://resources.matcha-jp.com/resize/720x2000/2017/07/30-32448.webp","https://resources.matcha-jp.com/resize/720x2000/2017/07/30-32447.webp"]'::jsonb, E'2017-11-03'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/7949', E'zh-Hans', 23, E'知多半島', E'知多半岛（日语：知多半島／ちたはんとう，罗马化：Chita hantō）为日本爱知县西部，名古屋市以南南北突出的一个半岛。\n\n西为伊势湾、东为知多湾・三河湾，与渥美半岛相望。半岛上主要为丘陵地形。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/09/18-86314.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/18-86312.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/18-86321.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/18-86320.webp"]'::jsonb, E'2020-02-24'::timestamptz, E'知多半島', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E7%9F%A5%E5%A4%9A%E5%8D%8A%E5%B3%B6'),
(E'https://matcha-jp.com/cn/20216', E'zh-Hans', 23, E'名古屋当日往返观光景点16选！可在2小时内乘车抵达！', E'名古屋位于东海地区，可方便前往近西关西等多个地区。本文介绍了从名古屋出发的一日游旅行推荐的16个景点，涵盖了温泉等各种地点。这些地点可在两小时内乘车抵达，同时开车也非常方便。同时也提到了可乘坐新干线到达的地区。\n\n名古屋，作为日本三大都市之一，是著名的丰田汽车的总部所在地，周边有许多迷人的旅游景点。\n\n这一次，住在名古屋多年的MATCHA员工们精心挑选了从名古屋出发的一日游理想地点。\n\n基本上，从名古屋站出发，你可以在2小时内到达这些地方！在文章中，我们还介绍了从名古屋站乘坐公共交通工具到达各地所需的时间。', E'["https://resources.matcha-jp.com/resize/720x2000/2023/11/27-153960.webp","https://resources.matcha-jp.com/resize/720x2000/2024/02/19-167371.webp","https://resources.matcha-jp.com/resize/720x2000/2023/11/24-153752.webp","https://resources.matcha-jp.com/resize/720x2000/2024/06/24-184945.webp"]'::jsonb, E'2024-06-25'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/4156', E'zh-Hans', 24, E'找出隐藏的忍者！伊贺铁道上野市站？', E'运行于三重县伊贺市的伊贺铁道有100年以上的历史了，已经成为当地居民以及游客们不可或缺的交通工具。本篇文章，小编将为大家介绍伊贺铁道上野市车站。\n\n运行于"忍者故乡" 三重县伊贺市的伊贺铁道，已经有100年以上的历史了，是当地居民以及观光客们经常使用的铁道。作为忍者列车的代表，其极具特色的车厢也被大家所熟知。\n\n包含列车在内，连车站都花了很多心思做了手工装饰。本篇文章小编将为大家介绍伊贺铁道上的核心车站，上野市站。\n\n由两种颜色粉刷而成的充满可爱感的上野市站列车站于1917年左右建立。其特色是三角屋顶，折纸风格的屋顶(腰折屋顶)，据说以前3楼部分是站长室。。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/04/08-23732.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/07-23641.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/07-23642.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/07-23646.webp"]'::jsonb, E'2017-11-03'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/7528', E'zh-Hans', 24, E'【三重 伊贺】昭和复古钱汤真霸主！文化遗产钱汤“一乃汤”', E'日本现存钱汤之中，只有5座被列为“物质文化遗产”，其中位于三重伊贺的“一乃汤”不只是作为钱汤历史最悠久，更是名符其实的“昭和复古钱汤”！刺青者无拒，也欢迎在不打扰客人的情况下拍照，想要“浸”入昭和，来这里准没错！\n\n目前全日本共有5处日本国家认定的“物质文化遗产钱汤”，各自拥有自己的特色与爱好者，今天要介绍的这间，则是喜爱钱汤的MATCHA小编心中最完美的“物质文化遗产钱汤”，更是“昭和复古风”的最佳代言人！\n\n三重县的“伊贺上野”被认为是忍者起源地之一，而全日本仅5座“物质文化遗产钱汤”中的“一乃汤”就位于此，仿佛习得忍术般静静地隐身巷弄，吸引各地的钱汤爱好者积极寻找拜访。\n\n这栋复古风味浓厚建筑诞生于1926年，当时的名字为“草津汤”，1926年是大正最后一年，也是昭和元年，这栋建筑确确实实走过整个昭和年代，也是5座物质文化遗产钱汤中，唯一建筑物从兴建至今保存完整，且作为钱汤历史上最悠久的一座。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/06/06-78897.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/06-78898.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/06-78896.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/06-78902.webp"]'::jsonb, E'2019-07-02'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/7166', E'zh-Hans', 24, E'【三重】似樱非樱、更胜一筹的梅花仙境！铃鹿之森庭园', E'每年2月下旬至3月下旬的铃鹿，总是吸引来自日本各地前来赏花的民众，他们的目标就是这期间限定的梅花仙境“铃鹿之森庭园”！\n\n从名古屋开车约一个多小时车程的三重县铃鹿地区，除了拥有铃鹿七大名山及驰名海外的铃鹿F1国际赛车场之外，这次小编要介绍一处鲜少外国人前往的粉色仙境“铃鹿之森庭园”，每到2月下旬至3月下旬，总是吸引来自日本各地前来赏花的民众。\n\n位于三重县北部的铃鹿之森庭园，是以八重梅的象征性品种“吴服枝垂”为中心，由赤冢植物园栽培研究的庭园，推广展现日本传统园艺的“枝垂梅嫁接技术”，平常则作为研究栽培的农园使用。\n\n园区内有约200多株的枝垂梅，吴服枝垂的垂坠方式有如烟花放射，其开花盛况一直被称为日本最大规模也最有魅力的巨树群，每年庭园会根据梅花开花时间对外开放参观，可以线上查询最新花况：https://twitter.com/Suzuka_Akatsuka', E'["https://resources.matcha-jp.com/resize/720x2000/2019/03/10-72817.webp","https://resources.matcha-jp.com/resize/720x2000/2019/03/10-72823.webp","https://resources.matcha-jp.com/resize/720x2000/2019/03/10-72824.webp","https://resources.matcha-jp.com/resize/720x2000/2019/03/10-72825.webp"]'::jsonb, E'2019-03-27'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/4646', E'zh-Hans', 25, E'琵琶湖國定公園', E'琵琶湖国定公园（日语：琵琶湖国定公園／びわここくていこうえん，罗马化：Biwako Kokutei Kōen），是位在日本滋贺县、京都府的国定公园。\n\n1950年7月24日指定，是日本最早指定的国定公园。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/06/26-29571.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/26-29559.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/26-29561.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/26-29562.webp"]'::jsonb, E'2017-10-30'::timestamptz, E'琵琶湖國定公園', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E7%90%B5%E7%90%B6%E6%B9%96%E5%9C%8B%E5%AE%9A%E5%85%AC%E5%9C%92'),
(E'https://matcha-jp.com/cn/11397', E'zh-Hans', 25, E'彥根城', E'彦根城是一所位于日本滋贺县彦根市金龟町的城堡，城内的天守名列日本国宝，亦为十二座现存天守之一。该城完整地保留了江户时代以前的筑城方式。\n\n别名金龟城（金亀城）。其建造耗时约20年，于1622年(元和8年)建成。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/10/25-131031.webp","https://resources.matcha-jp.com/resize/720x2000/2022/10/21-130979.png","https://resources.matcha-jp.com/resize/720x2000/2022/10/20-130958.jpeg","https://resources.matcha-jp.com/resize/720x2000/2022/10/21-130980.jpeg"]'::jsonb, E'2022-12-08'::timestamptz, E'彥根城', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%BD%A5%E6%A0%B9%E5%9F%8E'),
(E'https://matcha-jp.com/cn/9308', E'zh-Hans', 25, E'【关西】当地人首选，游客最爱！必须收藏的关西8间大型OUTLET与购物中心大解析', E'在关西地区也有众多OUTLET与购物中心方便大家购物游玩。像是离关西机场仅有一桥之隔的临空城OUTLET或神户三田OUTLET等 。 文中精选关西8间大型OUTLET和购物中心，从交通方式到推荐品牌详细介绍给大家。关西购物懒人包一定要永久收藏哦！\n\n关西地区美食美景云集自然是休闲旅游的好去处，此外像是心斋桥街或是梅田的百货公司等购物也很方便。 但其实关西还有不少大型OUTLET与购物中心，可以用非常优惠的价格入手各种好物。跟着小编一起来看看吧。\n\n关西的OUTLET和购物中心大多不在市中心，有些虽然较为偏远但是游客不多，可以悠闲购物，非常值得去走走。\n\n这边还有循环巴士可以载送您到临空城内的五间饭店，对住宿在关西机场附近的旅客来说很方便。', E'["https://resources.matcha-jp.com/resize/720x2000/2023/01/13-133733.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/22-95575.webp","https://resources.matcha-jp.com/resize/720x2000/2023/01/24-134033.webp","https://resources.matcha-jp.com/resize/720x2000/2023/01/24-134036.webp"]'::jsonb, E'2023-02-17'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/20621', E'zh-Hans', 26, E'体验日本文化！东京和京都的茶道、插花、世界遗产参观等套餐推荐', E'不妨尝试一些日本文化体验，让您的日本之旅更加特别！您可以通过茶道、插花、世界遗产、城堡、节日和季节性活动来感受日本的魅力。本文将介绍您可以在日本各地享受的文化体验和旅游景点，以及您可以参加的旅行团信息。\n\n生花是日本传统的插花艺术，注重花朵、枝条、容器和空间之间的和谐统一。生花以简洁的方式展现自然之美，如今以传统和自由两种风格广受人们喜爱。\n\n书法是日本传统的书写艺术。它运用毛笔和墨水，强调文字的形态之美、线条的动感以及留白的韵味。书法不仅仅是文字的记录，更是表达作者内心和个性的表达，是一种有助于心灵和谐的文化体验。\n\n京都是日本文化和精神遗产的中心，以其 1,600 多座佛教寺庙而闻名，其中包括金阁寺，其闪闪发光的金箔外墙反映了周围池塘的自然美景。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/06/06-235727.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/22-242115.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/22-242124.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/22-242117.webp"]'::jsonb, E'2025-06-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/25041', E'zh-Hans', 26, E'京都精緻日本料理：10家米其林指南推荐餐厅', E'这些京都的米其林星级餐厅提供精緻的怀石料理（套餐料理）与割烹风格菜餚，割烹较为亲民且更具弹性，但仍然非常优秀。我们的推荐范围涵盖祇园及京都市中心，靠近二条城和京都御苑。\n\n在京都品嚐精緻的日本料理 为了让您的京都之旅难以忘怀，品嚐精緻的日本料理是绝对不可或缺的。本店精心筛选了10家评价极高、屡获奖项并提供线上英文预订的餐厅，让国际来宾在体验京都最棒的美味时也感受到热情亲切。\n\n我们的选择涵盖割烹（Kappo）风格与怀石料理（Kaiseki）。 割烹相较较为亲民且气氛轻松，带有「家庭自製」的感觉；而怀石是日本高级的套餐料理，提供奢华的用餐体验，非常适合特殊庆典或想深度沉浸在日本料理艺术中的旅客。\n\n喜爱日本料理的食客绝不能错过Noguchi Tsunagu，这家与知名的「Kyotenjin Noguchi」姊妹店秉持着相同的料理哲学，并融入特色的五岛产食材，展现独特的风格。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/05/30-234917.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/30-234926.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/19-236869.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/30-234919.webp"]'::jsonb, E'2025-06-23'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/24939', E'zh-Hans', 26, E'【京都】2025年米其林指南餐厅15选！ 线上预约轻松享受京都顶级美食', E'在京都的米其林等级的高级餐厅中享受美味精緻的日本料理，所有餐厅皆可使用中文界面来线上预约，让你可以轻松体验日本美食。\n\n京都是优雅细腻、精緻料理的聚集地，因此米其林指南对该市的餐厅评价甚高。京都坚持传统烹饪风格的同时，也勇于融合现代元素，不断吸引来自全日本甚至国际的游客。\n\n以下这些餐厅都受到米其林指南的高度肯定，若想在京都享受难忘的用餐体验，不妨造访其中之一。\n\n藏身于传统的京都町屋内，圆融菴 小林提供米其林星级的天妇罗怀石料理，环境雅致且令人放松。每一道料理都经过深思熟虑，节奏感与层次感兼顾，让人从开胃到满足。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/05/19-233908.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/19-233910.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/19-233912.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/19-233914.webp"]'::jsonb, E'2025-06-05'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/26603', E'zh-Hans', 27, E'【由 TripToJapan 监督】春天出行的绝佳选择！大阪 3 个必游景点！', E'本文将介绍三个您应该参加的大阪春季旅游线路。\n\n在这1小时的行程中，您将跟随一位对当地路线了如指掌的专业导游，骑行穿梭于城市中心。您将途经美国村、心斋桥、道顿堀和难波等著名地区，感受活力四射的街道，体验令人兴奋的旅程。\n\n无论你是独自旅行还是与朋友结伴，都能与来自世界各地的冒险家们一起拥有难忘的体验。骑行穿过充满活力的大阪，感受微风拂面，你的兴奋之情只会与日俱增。\n\n在泉佐野的草莓实验室，您可以享受 40 分钟的草莓采摘体验，尽情品尝七种不同品种的草莓。', E'["https://resources.matcha-jp.com/resize/720x2000/2026/02/03-257532.webp","https://resources.matcha-jp.com/resize/720x2000/2026/02/03-257540.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/11-260891.webp","https://resources.matcha-jp.com/resize/720x2000/2026/02/03-257542.webp"]'::jsonb, E'2026-02-03'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/25670', E'zh-Hans', 13, E'东京・大坂米其林顶级「烧肉」10大餐厅推荐', E'搭配烧肉料理，客人在座位上品嚐到高品质的日本牛肉。探索东京和大坂的十大烧肉餐厅，包括获奖的知名店家和经济实惠的选择。\n\n烧肉是日本风格的烧烤方式，将小块肉和蔬菜在炭火或瓦斯烤炉上烤熟。"Yakiniku" 字面意思是「烤肉」。\n\n平常会用高品质的牛肉，例如和牛（Wagyu）、牛肋骨短排、沙朗牛排来烤，但也可以加入鸡肉、猪肉及蔬菜。烤好的食材通常会沾「 tare」酱料或塩来享用。\n\n烧肉在全日本都非常受欢迎，常见于专门的烧肉店、烧肉专卖店及家庭聚会中，以互动性高、社交氛围浓厚、重视肉品鲜味和高品质的烤肉风格而广受喜爱。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/08/27-242468.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/27-242445.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/27-242450.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/27-242452.webp"]'::jsonb, E'2025-08-27'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/23753', E'zh-Hans', 26, E'「吉伊卡哇」粉丝一起失心疯！大坂和京都的必去常设店和期间限定店', E'日本人气角色「吉伊卡哇」在世界上引起了一股可爱炫风。在关西的大坂和京都也能常常见到吉伊卡哇的身影，也有常设店舖可供粉丝购买具有当地特色的周边商品，这次就要和粉丝介绍关西地区的五家常设店铺与期间限定店，粉丝们不能错过！\n\n目前在关西地区有吉伊卡哇店舖的有大坂和京都这两地，其中在心斋桥PARCO除了常设外还有限定店舖，粉丝们一定要去朝圣！\n\n位于大坂梅田的吉伊卡哇LAND大坂梅田店，坐落于坂急三番街北馆的Kiddy Land内，是一个充满魅力的「吉伊卡哇」专属空间。这里陈列了丰富的周边商品，包含限量版周边和特色贩售品，还有可爱的展示区，是粉丝购物与打卡的理想地点。\n\n如果您在心斋桥附近，不妨前往吉伊卡哇LAND 心斋桥PARCO店，位于心斋桥PARCO的6楼。这家店铺延续了一贯的梦幻风格，商品类型多样，并且经常推出与其他地点不同的特色周边，是一个探索「吉伊卡哇」世界的好地方。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/01/23-220643.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/23-220654.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/23-220655.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/23-220656.webp"]'::jsonb, E'2025-02-12'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/1901', E'zh-Hans', 27, E'心斋桥商店街购物地图让你走到铁腿还是要买！', E'在大阪购物一定要去“心斋桥筋商店街”！这是一条长约600米，药妆店、美妆店、服饰店和餐厅等鳞次栉比的大型商店街。本篇详细介绍不同风格的推荐店铺和交通方式。\n\n这是离大坂观光据点难波和道顿堀较近的心斋桥。这里有大坂具有代表性的商店街「心斋桥筋商店街」。\n\n心斋桥筋商店街全长约600公尺。包含连接前后的其他商店街的话，成为一条约2公里延绵不断的商店街。聚集了药妆店、化妆品店、免税店、百圆店、动漫人物店、餐厅和咖啡店等，如果说想买的东西都可以在这里买到，一点也不过分。\n\n本篇为大家分类介绍心斋桥筋商店街都有什麽样的店铺！文章末尾也写着到达商店街的交通方式，看这一篇就不怕迷路啦！ 二手精品店「ALLU」优惠10,000日元', E'["https://resources.matcha-jp.com/resize/720x2000/2018/08/29-61550.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/29-61551.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/29-61552.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/28-61432.webp"]'::jsonb, E'2018-10-23'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/2517', E'zh-Hans', 27, E'【抹茶精选】关西绝景海滩5选', E'抹茶严选五处夏季期间在关西地区观光时还能顺便前往的海滩，邀您前来饱览关西清澈湛蓝\n\n来到夏天当然要玩海水浴！这次抹茶严选五处夏季期间在关西地区观光时还能顺便前往的海滩，邀您前来饱览关西清澈湛蓝大海。\n\n二色の浜海水浴场(两色沙滩海水浴场)其中「二色」是指延续约1公里的沙湾白以及海岸线处的松林绿。白沙与树木交织而成的景致相当美丽，从过去就以名胜景点广为人知，并获选为「大阪绿之百选（大阪みどりの百选）」。\n\n另外，欣赏这片绝景之余还能BBQ​​也是海滩的一大乐趣。从梅田站前来车程大约1小时。', E'["https://resources.matcha-jp.com/archive_files/jp/2016/07/dd1b52dfa690721794d4a37b1569200b.webp","https://resources.matcha-jp.com/archive_files/jp/2016/07/0534.webp","https://resources.matcha-jp.com/archive_files/jp/2016/07/832e740313485163ec3c41cae0beaed4.webp","https://resources.matcha-jp.com/archive_files/jp/2016/07/831ffcbdd4e69d89ff6e581519130e88.webp"]'::jsonb, E'2016-10-10'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/22181', E'zh-Hans', 28, E'【2024】兵库9个隐藏版枫叶景点精选！还介绍寺院和自驾游路线', E'不用担心不知道兵库有哪些红叶景点！本文将兵库推荐的红叶景点分为「隐藏版」、「寺院」和「自驾游」三类为您介绍。我们还总结了最佳观赏时间和夜间照明信息，请务必参考。\n\n兵库县有各种观光景点，包括美食和温泉。秋天时，山野变成红色和黄色，形成壮观的景象。\n\n本文将兵库县推荐的红叶景点分为「私密」、「寺院」和「自驾游」三类介绍。我们还总结了最佳观赏时间和夜间照明信息，请务必阅读到最后。\n\n园区举办由导游带领的「森林赏枫散步会」和「森林枫叶导览团」等活动，还有夜间照明，可以欣赏浪漫的景色。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/10/18-203473.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/18-203569.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/18-203581.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/18-203602.webp"]'::jsonb, E'2024-10-25'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/6379', E'zh-Hans', 28, E'神户观光15件心仪之事——模范路线、地区指南', E'好不容易来关西旅行，只去大阪、京都实在是可惜！离大阪和京都交通便利的神户，作为港口城市不仅拥有精致街景、时尚咖啡店、还有历史建筑物等众多好去处。小编将带大家游遍神户告诉大家神户有什么、怎么玩才尽兴！\n\n提到神户，大家都有什么印象呢？好吃的神户牛肉？或者在港町疯狂购物？想必很多人都对神户保有“距离大阪和京都较近的时尚都市”的印象吧。\n\n然而，神户其实是融合了多种文化，拥有多彩面貌的城市。自古以来作为港口城市，不仅带来繁荣发展，还将西洋文化与日本文化完美糅合在一起，最具代表的就是连绵不绝的精致街景。 另一方面，稍作移步便是日本最古老的温泉有马温泉和自然风情洋溢的六甲地区，纵横开阔。其他还有保留着下町气氛的商店街等。\n\n神户能让您尽享与您相宜的旅途形式。本篇从大致介绍神户的地区指南开始，到精选的神户15件心仪之事、模范路线，为大家毫无保留地介绍享受神户的方法！', E'["https://resources.matcha-jp.com/resize/720x2000/2018/09/04-62018.webp","https://resources.matcha-jp.com/resize/720x2000/2018/09/04-62019.webp","https://resources.matcha-jp.com/resize/720x2000/2018/09/05-62084.webp","https://resources.matcha-jp.com/resize/720x2000/2018/09/05-62085.webp"]'::jsonb, E'2018-11-19'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/11639', E'zh-Hans', 28, E'姬路城', E'姬路城（日语：姫路城／ひめじじょう，罗马化：Himeji-jō）是一座位于日本兵库县姬路市的城堡，为该市主体象征。由于其白色的外墙，也被称为白鹭城（白鷺城／はくろじょう・しらさぎじょう）。\n\n作为日本最具象征意义，且保留度最为完整的城堡，姬路城是日本政府指定的国宝及国家特别史迹，也是日本首批世界文化遗产之一。为日本100名城之一。\n\n由于其保存度相当完好（城内的天守为日本的十二座现存天守之一），也被称为“日本第一名城”。许多时代剧和电影也在这里进行拍摄，或以姬路城作为江户城的象征。', E'["https://resources.matcha-jp.com/resize/720x2000/2023/01/06-133555.webp","https://resources.matcha-jp.com/resize/720x2000/2023/01/06-133556.webp","https://resources.matcha-jp.com/resize/720x2000/2023/01/06-133558.webp","https://resources.matcha-jp.com/resize/720x2000/2023/01/06-133559.webp"]'::jsonb, E'2023-01-25'::timestamptz, E'姬路城', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%A7%AC%E8%B7%AF%E5%9F%8E'),
(E'https://matcha-jp.com/cn/19933', E'zh-Hans', 29, E'东大寺', E'东大寺（日语：東大寺／とうだいじ，罗马化：Tōdai Ji）位于日本奈良县奈良市杂司町，是日本佛教华严宗大本山、南都七大寺之一。\n\n1998年作为“古都奈良的文化财”的一部分被列为世界文化遗产。东大寺由信奉佛教的圣武天皇兴建于728年，因为建在首都平城京以东而得名，另外有西大寺相对应。\n\n其后圣武天皇在日本各地兴建68馀座国分寺（正式名称为“金光明四天王护国之寺”），东大寺是阶位最高的总寺院。此寺大佛殿正面宽度57米，深50米，为世界最大的木造建筑，殿内供奉高15米以上的卢舍那大佛像。\n\n寺院内还有南大门、二月堂、三月堂、正仓院等建筑，其中南大门有很著名的双体金刚力士像；二月堂能够俯视大佛殿和眺望奈良市区。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/09/18-197922.webp","https://resources.matcha-jp.com/old_thumbnails/200x2000/2600.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/20-198167.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/20-198169.webp"]'::jsonb, E'2024-10-02'::timestamptz, E'东大寺', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E4%B8%9C%E5%A4%A7%E5%AF%BA'),
(E'https://matcha-jp.com/cn/5095', E'zh-Hans', 29, E'祭祀日本最大的骑士像，奈良县的“安倍文殊院”有什么魅力？', E'奈良县樱井市的安倍文珠院，与京都府「切戸文珠」及山形县「亀冈文珠」视为日本三文珠之一。文殊指的是负责智慧且次於佛的等级。安倍文珠院不仅有日本最大的文殊菩萨像，境内的金阁浮御堂相当地美丽，春天可以赏樱，秋天还可以看到大波斯菊绽放。\n\n当时也称作为安倍寺或崇敬寺，而且是在距离现在位置西南方300米处的地方。于镰仓时代(1185～1333年)被迁移。\n\n※1：氏寺……祈求特定一族之繁荣及祖先在天之灵所建造的寺院。常会取名为“○○家之氏寺”“○○一族之氏寺”。现在即使是同族以外的人也可参拜。\n\n安倍文殊院的本尊(※2)文殊菩萨像高达7米，是日本最大的骑士像。右手持着象征智慧的驱魔斩恶的利剑，左手持着莲华。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/09/24-36865.webp","https://resources.matcha-jp.com/resize/720x2000/2017/09/24-36863.webp"]'::jsonb, E'2017-12-17'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/5436', E'zh-Hans', 29, E'绝不只有鹿！日本奈良特色与魅力还有这些', E'奈良和京都、大坂、神户都被属于关西，但相较京坂神，奈良似乎较不被了解。对于奈良的印象，不外乎就是“大佛”、“鹿”，但其实奈良还有其他特色。既然奈良人不擅长宣传自己，那这次就由MATCHA 小编来让大家更认识奈良吧！\n\n相较于观光客熟知的京都、大坂，同样位在关西的奈良似乎较不被了解。对于奈良的印象，不外乎就是“大佛”、“鹿”，但其实奈良还有其他特色。本篇不教大家如何抵达奈良喂鹿，而是要告诉你奈良和京都、大坂等其他县市有何不同，既然奈良人不擅长宣传自己，那这次就由MATCHA 小编来让大家更认识奈良吧！\n\n日本历史上名叫“飞鸟”的地方就是在现今的奈良“明日香村”，其为日本最古老的京城。因为京城不断迁移，后来才定在京都。换句话说，在京都变为首都之前，首都一直在奈良。\n\n相较于京都的优雅尊贵的和风情怀，对于奈良的印象大多被认为较朴实、甚至古得有些土气。但曾有位日本艺人说过“过了三十岁后，慢慢能发现奈良的魅力。”相较于充满观光客的拥挤巷弄，走在奈良显得悠闲许多，能细细品味拥有千年以上历史的建筑、古迹，若想亲自见证“最原始的日本”，那么你一定要来奈良看看。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/11/29-42592.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/29-42588.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/29-42587.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/29-42589.webp"]'::jsonb, E'2017-12-05'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/4136', E'zh-Hans', 30, E'【和歌山县】大海与温泉的独家胜地 “白浜温泉”旅游指南', E'白浜是能够同时享受到大海与温泉的独家胜地。在这里，大家可以一边泡着温泉，一边享受着美丽的海景。本篇文章介绍了白浜温泉的功效、交通方法、当日往返的入浴景点和推荐旅馆等旅游情报。\n\n白浜是地处和歌山县南部的观光地。这里也被称作南纪白浜，在关西地方作为大海与温泉的度假胜地而广为人知。\n\n白浜温泉就处于白浜之中。这里与有马温泉、道后温泉共称为日本三大古汤，历史悠久，甚至还有记录显示在6世纪到8世纪，当时的天皇也曾前往此处泡汤。白浜温泉有众多的外汤和足汤，前往各个外汤泡澡也是乐趣之一。欢迎大家在这里一边泡汤一边感受近在咫尺的太平洋，享受这里独特的开放感吧。\n\n照片提供：白浜观光协会 白浜温泉延续了1,300年之久的人气，来源于泉质的优良。白浜温泉的泉质不是单独的一种，根据取水地步同，泉质也有所差异，因此旅馆和各个温泉设施内的泉质和功效也是不一样的。在这之中最为主要的3种是氯化钠泉、中性高渗高温泉、弱碱性低渗高温泉，这些泉水一般会对肌肉痛、关节痛、体寒、慢性皮肤病等有良好的效果。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/03/06-20648.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/06-20649.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/06-20650.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/06-20651.webp"]'::jsonb, E'2017-08-10'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/4879', E'zh-Hans', 30, E'【和歌山】世界遗产熊野三山，灵魂终点生命起点“熊野本宫大社”', E'和歌山的熊野三山，又称为熊野三社，皆在熊野古道名列世界遗产，被誉为“神灵居住之地”，这里的一切与自然息息相关，是日本人的心灵圣地。其中坐落和歌山县山林之中的熊野本宫大社，大斋原被称为灵魂的终点、生命的起点，同时也是拥有日本最大的鸟居。\n\n熊野三山，又称为熊野三社，包括熊野速玉大社、熊野本宫大社与熊野那智大社。至三社所经的熊野古道与神社名列世界遗产，被誉为“神灵居住之地”，这里的一切与自然息息相关，是日本人的心灵圣地。\n\n位于和歌山的熊野古道，距今已有超过千年历史。传说在一一六四年，神明降临熊野地区，这里遂成为“神灵居住之地”，信徒远从全国各地而来，人数之多，让古道上满是人潮，被称为蚂蚁的熊野参拜（蚁の熊野诣）。2004年，以“纪伊山地的圣地与参拜道”，简称熊野古道，登录世界遗产，也是世界唯二登录世界遗产的古道。\n\n熊野本宫大社，位于和歌山县田边市本宫町，处于山林之中，可以由JR新宫站、JR那智站或JR胜浦站乘坐巴士前往，单趟1540元，若是想体验古人参拜临场感，可以乘坐巴士至古道中边路区，再攀爬石阶前往本宫大社。古道路线请参考这边', E'["https://resources.matcha-jp.com/resize/720x2000/2017/08/02-32723.webp","https://resources.matcha-jp.com/resize/720x2000/2017/08/13-33432.webp","https://resources.matcha-jp.com/resize/720x2000/2017/08/13-33433.webp","https://resources.matcha-jp.com/resize/720x2000/2017/08/13-33434.webp"]'::jsonb, E'2017-11-25'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/2033', E'zh-Hans', 30, E'【废墟】仿佛天空之城的世界！和歌山县友之岛「第3炮台遗迹」', E'吉卜力工作室的『天空之城』是一部在日本不断重复播放的人气经典电影作品，而能感受到『天空之城』世界观的无人岛就位于和歌山县。这次就介绍给大家「友之岛」。\n\n友之岛只能搭船前往，首先得先到和歌山县和歌山市的加太港。若要从和歌山市中心前往加太港，可先从南海电铁加太线的和歌山市站搭乘至加太站，再步行15分钟左右即可抵达。走到港口一带，就能看见前往友之岛的指示。\n\n请先在此购买船票。每趟搭船人数有限，售完则无法搭乘，因此建议尽早前往购票。全票来回2,000日元，孩童来回1,000日元。\n\n航程约20分钟即可抵达友之岛，海浪平稳摇摆，海风拂面而过。在岛内的时光，更是悠闲恣意。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/03/03-123462.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/03-123463.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/03-123464.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/03-123465.webp"]'::jsonb, E'2016-09-01'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/3725', E'zh-Hans', 31, E'【山阴】鸟取好好玩 ！内行人必去五大超推景点', E'鸟取，一个常跟岛根傻傻分不清楚的地方。在2016年“全国47都道府县魅力排行”中，更获得倒数第五名，鸟取真的如此的没魅力吗？不不不~鬼太郎作者故乡,柯南博物馆,鸟取沙丘,白兔神社等等地点可多着呢！快跟Matcha小编一起看下去吧！\n\n提到鸟取，别说旅客常搞混，就连日本人也常常将鸟取与隔壁的岛根搞错。在2016年“全国47都道府县魅力排行”中，鸟取县获得倒数第五名，远远落后隔壁岛根县。鸟取县真的有这么无聊吗？其实鸟取有很多景点，内行人都知道，但是内行人都不说，今天就一起揭开鸟取县充满魅力的景点吧！\n\n日本公认的妖怪博士，经典妖怪漫画“鬼太郎”的作者水木茂老师，出身正是鸟取县，大师故乡的境港，也顺理成章地成为鬼太郎的故乡。鸟取县相当敬重水木茂老师，也把鬼太郎当作地方骄傲，从把鸟取县米子机场取名为“米子鬼太郎机场”就可略知一二，当然地上跑的电车也没放过，一样设计成鬼太郎列车。\n\n境港处处可见鬼太郎作品里的人物雕像，连路灯、计程车等，也都是与鬼太郎相关的设计。其中这个位于车站前的雕像，刻画的是鬼太郎与鼠男，望着创作自己的水木茂大师的场景，让人备感温馨，而水木茂老师本人也已于2016年底逝世，但粉丝们都觉得老师一定是开心地与鬼太郎们跑去找妖怪玩了。', E'["https://resources.matcha-jp.com/resize/720x2000/2016/12/13-11549.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/13-11550.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/13-11551.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/12-11443.webp"]'::jsonb, E'2018-02-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/5457', E'zh-Hans', 31, E'日本第一的能量景点。到鸟取拥抱美丽大自然和绝景疗愈身心吧', E'日本存在很多和神道佛教等渊源深厚的能量景点，比如著名的明治神宫、和歌山县的高野山等景点。其实鸟取县也有两处人气能量景点，其一是“日本最危险的国宝”三德山三佛寺投入堂，三德山作为山岳佛教“修验道”者修行场所，至今向人们传递着净化身心的力量，还有就是拥有“日本最长自然石参道”的大神山神社奥宮。\n\n在鸟取县存在着不少能力景点，带有浓厚的日本传统神道和佛教色彩，穿越历史向现代人传递着各种精神能量。\n\n鸟取县中部有很多人气景点，比如柯南迷必去的动漫《名侦探柯南》的世界：青山刚昌故乡馆，比如保留有江戸・明治时代风貌的白壁土藏群等。我们把JR仓吉站作为旅游的交通据点，而从这里出发坐巴士约30分钟便可抵达一处名为三德山的地方。\n\n据传从8世纪开始，三德山便成为了修验道(※1)的修行场所。而建于三德山海拔520米绝壁处，便是有着“日本最危险的国宝”之称的投入堂。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/12/04-42992.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/09-43456.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/04-42993.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/09-43457.webp"]'::jsonb, E'2018-03-22'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/10935', E'zh-Hans', 31, E'畅游冈山、鸟取、岛根之美推荐使用「山阳&山阴地区铁路周游券」最实惠！', E'JR西日本的“山阳&山阴地区周游券”是7天有效的周游券。 这一次，我们将向您介绍使用周游券参观的冈山县、鸟取县和岛根县的代表性的景点。 同时还会介绍新型冠状病毒防疫措施下新的售票方式。\n\n对于来日本观光的旅客来说，交通费是一大烦恼。这种情况下只要使用各个铁路公司的周游券，在省钱的同时还能节省时间！不用在意交通成本，尽情得享受旅程吧！\n\n特别是想要周游西日本的旅客，“山阳&山阴地区周游券”是您不二的选择。此周游券可以在7天内连续使用，适用范围如上图所示，还可以搭乘山阳新干线及其区间内特快列车的指定席，从大阪关西国际机场一下飞机就可以使用。\n\n最重要的是，7天只需要20000日元（含税*海外销售价格），平均一天都不要2900日元，真是非常划算。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/01/04-119146.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/04-119118.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/04-119120.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/04-119119.webp"]'::jsonb, E'2021-12-16'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/7642', E'zh-Hans', 32, E'宍道湖', E'宍道湖（日语：宍道湖／しんじこ，罗马化：Shinjiko）是位于日本岛根县松江市与出云市之间的一座湖泊，其北岸、东岸、南岸都属于松江市，西岸属于出云市，面积为日本第七大的湖泊。\n\n宍道湖呈东西向狭长型，东西方向长约17公里，南北方向约6公里；湖底大致平坦，约五成以上的区域水深超过5公尺。湖水水源主要来自西侧的斐伊川本川，除了斐伊川外，其他还有约20条河川流入湖内；而湖水出口在东侧，经由大桥川接入中海后再经由境水道流入日本海的美保湾，因此宍道湖与中海一同被视为一级水系斐伊川主流的一部分，而斐伊川流入宍道湖之前的部分则称为“斐伊川本川”。\n\n此外，在北岸有一条在18世纪末挖掘用于排水的人工运河佐陀川可直接将湖水导入日本海。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/07/09-81186.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/04-85224.webp","https://resources.matcha-jp.com/resize/720x2000/2019/07/09-81187.webp","https://resources.matcha-jp.com/resize/720x2000/2019/07/09-81188.webp"]'::jsonb, E'2019-10-26'::timestamptz, E'宍道湖', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%AE%8D%E9%81%93%E6%B9%96'),
(E'https://matcha-jp.com/cn/8269', E'zh-Hans', 32, E'玉造溫泉', E'玉造温泉是位于日本岛根县松江市玉汤町玉造地区的温泉区，为“枕草子・三大名泉”之一；其不论是规模或是历史，都是岛根县内最具代表性的温泉区。\n\n温泉泉质属于硫酸盐盐化物泉，源泉温度超过42度。温泉区主要分布于玉汤川沿岸，也是松江市内的主要观光景点之一，区内许多温泉旅馆为数寄屋造风格的高级日式旅馆。\n\n其中也有大众浴池“玉造温泉Yuyu”（玉造温泉ゆ〜ゆ）。近年以“美肌温泉”及周边区域的出云大社、八重垣神社、玉作汤神社的“结缘”为宣传主轴，锁定女性顾客为主要对象，甚至还有厂商以“玉造温泉水”推出化妆品。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/12/05-92395.webp","https://resources.matcha-jp.com/resize/720x2000/2019/12/09-92578.webp","https://resources.matcha-jp.com/resize/720x2000/2019/12/09-92581.webp","https://resources.matcha-jp.com/resize/720x2000/2019/12/09-92582.webp"]'::jsonb, E'2019-12-26'::timestamptz, E'玉造溫泉', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E7%8E%89%E9%80%A0%E6%BA%AB%E6%B3%89'),
(E'https://matcha-jp.com/cn/3804', E'zh-Hans', 32, E'【岛根县】14年连续蝉联第一的日本庭园！“足立美术馆”', E'“足立美术馆”位于岛根县安来市，以日本画为中心展示各种艺术作品。美术馆的面积有5万坪之大，打造了许多山水美景，是日本国内最大的庭园。\n\n美国的日本庭园杂志《SUKIYA LIVING MAGAZINE》中，这个庭园在排行榜已经蝉联17年第一，豪无疑问是日本最具代表性的庭园了。\n\n足立美术馆分成两个部分。本馆是展示近代日本画、陶艺以及庭园。新馆则是展示现代日本画和企划活动专区。如果想看庭园，就来去本馆吧。\n\n足立美术馆的构想是将“日本庭园和日本画中的意境融合起来”。本馆1楼可以观赏庭园景观。到了2楼会看到日本画名匠横山大观等等大师级的作品，这也是创立者足立全康心爱的收藏。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/01/28-15155.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/28-15151.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/28-15161.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/28-15162.webp"]'::jsonb, E'2018-01-22'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/3744', E'zh-Hans', 33, E'【仓敷】女子力行程这样排！吸睛美食与必拍景点一日散策', E'冈山县仓敷市，是江户幕府时代的直辖地区，当时相当䌓华的城镇。至今还保留着町屋和仓房，各处的白墙砖瓦迷漫着历史气息，近年有不少特色咖啡美食与杂货小店进驻，还有MT纸胶带工房，是个女子力极高又能享受惬意的好地方！来看看MATCHA小编排的示范行程与推荐住宿吧！\n\n冈山县仓敷市，是江户幕府时代的直辖地区，当时是相当䌓华的城镇。至今，还保留着町屋和仓房，各处的白墙砖瓦与柳树并木都迷漫着历史气息，而主要观光景点就位于仓敷的美观地区，是个悠闲散步的好地方。 大原美术馆等美术馆也聚集在此，因此也被称为艺术之街。而近年也有许多现代手工杂货以及ＭＴ纸胶带专卖店进驻，还有提供香甜季节白桃水果甜点的咖啡店，吸引许多女生前往。\n\n从冈山站搭上JR山阳本线，花17分钟左右抵达仓敷站；再从仓敷站走到美观地区，步行15分钟。 JR单程票价320日元。\n\n大原美术馆的馆藏有毕卡索和莫内、高更等世界级大师的作品，以及日本画、雕刻等各种收藏。美术馆内的庭园“新溪园”，随着春夏秋冬变化，呈现各种美丽景色，也是人气景点之一。详细请见“大原美术馆”。 (图为工艺 东洋馆)', E'["https://resources.matcha-jp.com/resize/720x2000/2019/08/15-83970.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/15-83972.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/14-83928.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/14-83929.webp"]'::jsonb, E'2017-08-24'::timestamptz, null, null, null)
